<?php namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;use App\Models\{CartItem,ProductVariant,User};
class CartController extends Controller {
 public function index(){return view('cart',['items'=>CartItem::where('user_id',auth()->id())->with('variant.product')->get()]);}
 public function store(Request $r){$d=$r->validate(['variant_id'=>'required|integer|exists:product_variants,id','quantity'=>'required|integer|between:1,1000']);DB::transaction(function()use($r,$d){User::whereKey($r->user()->id)->lockForUpdate()->firstOrFail();$v=ProductVariant::with('product')->findOrFail($d['variant_id']);$item=CartItem::firstOrNew(['user_id'=>$r->user()->id,'variant_id'=>$v->id]);$qty=($item->quantity??0)+$d['quantity'];$this->check($v,$qty);$item->quantity=$qty;$item->save();});return $r->expectsJson()?response()->json(['success'=>true,'cartCount'=>CartItem::where('user_id',$r->user()->id)->sum('quantity'),'message'=>'Đã thêm vào giỏ.']):redirect('/cart')->with('success','Đã thêm vào giỏ.');}
 private function check($v,$qty){if(!$v->is_active||!$v->product->is_active||$qty>$v->stock)throw ValidationException::withMessages(['quantity'=>'Sản phẩm đã ẩn hoặc số lượng vượt tồn kho.']);}
 public function update(Request $r,CartItem $cartItem){abort_unless($cartItem->user_id===$r->user()->id,403);$d=$r->validate(['quantity'=>'required|integer|between:1,1000']);DB::transaction(function()use($r,$cartItem,$d){User::whereKey($r->user()->id)->lockForUpdate()->firstOrFail();$item=CartItem::findOrFail($cartItem->id);$this->check($item->variant,$d['quantity']);$item->update($d);});return back()->with('success','Đã cập nhật giỏ.');}
 public function destroy(Request $r,CartItem $cartItem){abort_unless($cartItem->user_id===$r->user()->id,403);DB::transaction(function()use($r,$cartItem){User::whereKey($r->user()->id)->lockForUpdate()->firstOrFail();CartItem::whereKey($cartItem->id)->delete();});return back()->with('success','Đã xóa khỏi giỏ.');}
}
